import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.BN2sqjC1.js";const v=JSON.parse('{"title":"ADR-0057 — Identità del dispositivo desktop per hostname e revoca al logout (M21, Onda C)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0057-identita-dispositivo-desktop-hostname.md","filePath":"adr/0057-identita-dispositivo-desktop-hostname.md"}'),c={name:"adr/0057-identita-dispositivo-desktop-hostname.md"};function n(s,e,d,r,l,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0057-—-identita-del-dispositivo-desktop-per-hostname-e-revoca-al-logout-m21-onda-c" tabindex="-1">ADR-0057 — Identità del dispositivo desktop per hostname e revoca al logout (M21, Onda C) <a class="header-anchor" href="#adr-0057-—-identita-del-dispositivo-desktop-per-hostname-e-revoca-al-logout-m21-onda-c" aria-label="Permalink to &quot;ADR-0057 — Identità del dispositivo desktop per hostname e revoca al logout (M21, Onda C)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-16, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.7 (2026-11-16); implementata e rilasciata con la 1.7.2</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.7 (2026-11-16): §1.7, §2.6.1, §3.2.2 (DDL di <code>devices</code> ed elenco delle migrazioni), §3.5.1 e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.7 («Identità del dispositivo» e «Dispositivo revocato», <code>Specifications.md:286-287</code>); §2.6.1 (registro <code>devices</code>, <code>:537</code>); §3.2.2 (DDL della tabella <code>devices</code>, <code>:814</code>); §3.5.1 (<code>POST /me/devices</code> e <code>DELETE /me/devices/{id}</code>, <code>:1265-1266</code>); ADR-0012 (dispositivi nella console), ADR-0029 (il browser come dispositivo <code>web</code>, identità in IndexedDB), ADR-0037 e ADR-0045 (voci <code>devices</code> e <code>devices.revoked</code> di <code>shared/parity/features.yaml</code>)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì, in due punti:</strong> (1) §3.2.2 e §3.5.1: la tabella <code>devices</code> ha una colonna <code>hostname</code> e un indice unico parziale, e <code>POST /me/devices</code> per le piattaforme desktop riattiva la riga dello stesso hostname invece di crearne una nuova; (2) §1.7 non dice nulla sul logout del desktop, che ora revoca il proprio dispositivo. <strong>§1.7 «Dispositivo revocato» non cambia:</strong> il client si ferma e <strong>offre</strong> «Registra di nuovo questo dispositivo», senza ripetere la registrazione da solo (vedi «Punto aperto, risolto»). Il workbench web non cambia. Da recepire nello spec v1.7 (<a href="./../spec-v1.7-proposta.html"><code>spec-v1.7-proposta.md</code></a>): §1.7 (logout e identità per hostname), §3.2.2, §3.5.1 e l&#39;elenco dei dispositivi di §2.6.1</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: unit di <code>apps/desktop/internal/auth/logout_test.go</code>, <code>TestLogoutRevokesDeviceAndEndsIdentityProviderSession</code>, <code>TestLogoutNeverBlocksOnNetworkFailures</code>, <code>TestLogoutSkipsRevokedDevice</code>, <code>TestDeviceNameFromEnvironment</code>; unit di <code>internal/sync/manager_pause_test.go</code> su <code>PauseAll</code>; <code>task test-desktop-e2e</code>: registrazione, revoca e nuova registrazione con lo stesso nome nei test di <code>internal/sync</code>) · workbench web (invariato: piattaforma <code>web</code>, identità in IndexedDB, nessuna modifica; resta valida la voce <code>devices</code> del registro) · console (nessuna modifica di interfaccia: dopo un nuovo accesso l&#39;elenco mostra la stessa riga) · cloud (migrazione <code>0016</code>, query <code>UpsertDesktopDevice</code>, <code>users.Service.RegisterDevice</code>; prove: integrazione con testcontainers in <code>services/cloud/test/integration/device_hostname_test.go</code>, <code>task test-integration</code>). Registro: voci <code>devices</code> e <code>devices.revoked</code>, senza nuove funzioni</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Sul cloud di E2BR l&#39;elenco dei dispositivi di un utente mostra più righe per la stessa macchina. La causa è in tre punti, tutti verificati nel codice:</p><ul><li><strong>Il logout del desktop non revoca il dispositivo.</strong> <code>Service.Logout</code> (<code>apps/desktop/internal/auth/auth.go:619-631</code>) revoca il refresh token, poi <code>clearSession</code> cancella <code>auth.json</code> (<code>deleteSession</code>, quando la sessione non è ospitata) e con esso il <code>device_id</code>. Il dispositivo resta attivo sul cloud.</li><li><strong>Il login successivo ne registra uno nuovo.</strong> <code>completeSession</code> (<code>auth.go:322-368</code>) chiama <code>RegisterDevice</code> quando <code>sess.DeviceID</code> è vuoto. Il nome è <code>os.Hostname()</code> (<code>auth.go:191-196</code>).</li><li><strong>Il server non ha alcun vincolo di unicità.</strong> <code>devices</code> ha solo la chiave primaria e l&#39;indice <code>devices_user_ix</code> non unico (<code>0001_core.sql</code>); <code>CreateDevice</code> inserisce sempre una riga nuova; la sola protezione è <code>Idempotency-Key</code>, che il client genera a caso a ogni chiamata e che serve per i tentativi ripetuti, non per l&#39;identità (<code>users/service.go:217-250</code>).</li></ul><p>Il browser è già un caso risolto: un dispositivo <code>web</code> per profilo del browser, con l&#39;identità in IndexedDB fuori dalla cartella cancellata dal logout (ADR-0029, §1.7). Per il desktop manca l&#39;equivalente.</p><p>Oggi un dispositivo revocato dalla console fa rispondere al <code>commit</code> <code>403 FORBIDDEN</code> con <code>extra.reason = &quot;device_revoked&quot;</code> (<code>sync/service.go:126-137</code>); il client entra nello stato <code>device_revoked</code> (<code>auth.Service.DeviceRevoked</code>, <code>auth.go:392</code>) e offre «Registra di nuovo questo dispositivo» (<code>ReregisterDevice</code>, <code>auth.go:414</code>). Un <code>device_id</code> che non esiste risponde <code>400 VALIDATION_FAILED</code> con dettaglio <code>unknown device_id</code> (<code>sync/service.go:128</code>): il client non lo distingue da altri errori di validazione.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Il desktop è identificato dall&#39;hostname, per utente e piattaforma. Il browser resta com&#39;è.</strong></p><h3 id="cloud" tabindex="-1">Cloud <a class="header-anchor" href="#cloud" aria-label="Permalink to &quot;Cloud&quot;">​</a></h3><ol><li><strong>Migrazione <code>services/cloud/internal/db/migrations/0016_device_hostname.sql</code>:</strong><ul><li>aggiunge la colonna <code>hostname text</code>, valorizzata con <code>lower(name)</code> per le righe con <code>platform IN (&#39;windows&#39;,&#39;macos&#39;,&#39;linux&#39;)</code> (NULL per <code>web</code>);</li><li>deduplica: per ogni gruppo <code>(user_id, platform, hostname)</code> resta attiva la riga con <code>last_seen_at</code> più recente; le altre ricevono <code>revoked_at = now()</code> e <code>hostname = NULL</code>. <strong>Le righe non si cancellano</strong>: le revisioni dei file puntano a <code>device_id</code> e lo storico non perde l&#39;autore;</li><li>crea l&#39;indice unico parziale su <code>(user_id, platform, hostname) WHERE hostname IS NOT NULL</code>.</li></ul></li><li><strong>Query <code>UpsertDesktopDevice</code></strong> in <code>internal/db/queries/users.sql</code>: <code>INSERT … ON CONFLICT (user_id, platform, hostname) WHERE hostname IS NOT NULL DO UPDATE SET revoked_at = NULL, last_seen_at = now(), app_version = EXCLUDED.app_version, name = EXCLUDED.name RETURNING *</code>. Il nome conserva le maiuscole ricevute; <code>hostname</code> è sempre <code>lower(name)</code>. <strong>Come implementato</strong> (<code>0016_device_hostname.sql</code>, <code>UpsertDesktopDevice</code>): <code>hostname</code> è <code>lower(btrim(name))</code> (spazi ai lati tolti; la migrazione salta i nomi vuoti), e <code>app_version</code> e <code>Idempotency-Key</code> non si azzerano se la nuova registrazione non ne porta uno (<code>COALESCE</code>).</li><li><strong><code>users.Service.RegisterDevice</code></strong> usa l&#39;upsert per <code>windows</code>, <code>macos</code> e <code>linux</code>; per <code>web</code> resta <code>CreateDevice</code>. Il replay dell&#39;<code>Idempotency-Key</code> resta <strong>prima</strong> dell&#39;upsert e vale per entrambe le strade.</li><li><strong>Contratto.</strong> Nessun campo nuovo in <code>DeviceRegistration</code> né in <code>Device</code>. <code>api/openapi.yaml</code> documenta che per le piattaforme desktop <code>name</code> è l&#39;hostname e identifica il dispositivo dell&#39;utente: registrare di nuovo lo stesso <code>name</code> e la stessa piattaforma restituisce <strong>lo stesso <code>id</code></strong>, riattivato se era revocato. La risposta resta <code>201</code> (oggi <code>RegisterDevice</code> in <code>users/http.go</code> risponde solo <code>201</code>, e il contratto non ha altri codici di successo): un client non deve dedurre dal codice se il dispositivo è nuovo.</li></ol><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><ol start="5"><li><strong><code>Logout</code></strong> (<code>auth.Service.Logout</code>, <code>auth.go</code>), in quest&#39;ordine: (a) ferma la sync: l&#39;app passa <code>BeforeLogout</code>, che chiama <code>sync.Manager.PauseAll</code> (ferma il ciclo di ogni vault e aspetta al massimo 5 s che quello in corso torni; i motori restano com&#39;erano e nulla di locale si tocca); (b) <code>revokeThisDevice</code> chiama <code>RevokeDevice</code> sul cloud (<code>transport.Client.RevokeDevice</code>), a miglior sforzo, mentre il token è ancora valido; non fa nulla se il dispositivo non ha <code>device_id</code> o è già segnato revocato; (c) termina la sessione dall&#39;identity provider (ADR-0058); (d) <code>clearSession</code>. I passi di rete (b e c) hanno un tetto comune di 8 s (<code>logoutNetworkTimeout</code>). Se la rete manca la revoca fallisce, si scrive nel log e il logout prosegue: la riga resta attiva, e il login successivo la riprende per lo stesso hostname. Una sessione ospitata (il core nel browser) non esegue nulla di tutto questo.</li><li><strong>Login.</strong> <code>RegisterDevice</code> con lo stesso hostname restituisce lo stesso <code>id</code>. I <code>sync.db</code> dei vault che conservano <code>MetaDeviceID</code> si riallineano come oggi (<code>sync/manager.go:447-463</code>, <code>sessionDeviceApplies</code>).</li><li><strong>Nessuna nuova registrazione automatica.</strong> Un dispositivo revocato dalla console lascia il client nello stato <code>device_revoked</code> (<code>auth.Service.DeviceRevoked</code>): la sync si ferma e il pulsante «Registra di nuovo questo dispositivo» (<code>ReregisterDevice</code>) resta l&#39;unico modo di riprendere, come dice §1.7. Il pulsante riattiva <strong>la stessa riga</strong> grazie all&#39;upsert del punto 2, quindi non crea duplicati. <strong>Un <code>device_id</code> che il cloud non conosce non porta a questo stato:</strong> il <code>commit</code> risponde <code>400 VALIDATION_FAILED</code> con dettaglio <code>unknown device_id</code> (<code>services/cloud/internal/sync/service.go:128</code>) e il client riconosce la revoca solo dal <code>403 FORBIDDEN</code> con <code>extra.reason = &quot;device_revoked&quot;</code> (<code>apps/desktop/internal/sync/transport/client.go</code>, <code>ErrDeviceRevoked</code>): per un id sconosciuto non c&#39;è oggi un percorso di ripresa automatico né il pulsante (correzione del testo del 2026-11-16, allineato al codice; non cambia la decisione). Il piano di M21 prevedeva una ripetizione automatica; non è stata implementata (vedi «Punto aperto, risolto»).</li><li><strong>Override del nome:</strong> la variabile d&#39;ambiente <code>CLARAE_DEVICE_NAME</code> (costante <code>auth.DeviceNameEnv</code>), letta da <code>auth.New</code> quando <code>Options.DeviceName</code> è vuoto (spazi ai lati tolti), prevale su <code>os.Hostname()</code>. Serve ai test e a due istanze sullo stesso computer, che altrimenti diventerebbero un solo dispositivo. <code>scripts/run-desktop-with-cloud.sh --two-devices</code> la imposta per ogni istanza a <code>&lt;hostname breve&gt;-dev&lt;n&gt;</code>. I test di <code>task test-desktop-e2e</code> non la leggono: scelgono un nome diverso per dispositivo (<code>uniqueDeviceName</code>, <code>internal/sync/e2e_test.go</code>).</li><li><strong>Workbench web: nessuna modifica.</strong> Resta un dispositivo <code>web</code> per profilo del browser, con l&#39;identità in IndexedDB (§1.7).</li></ol><h3 id="prove" tabindex="-1">Prove <a class="header-anchor" href="#prove" aria-label="Permalink to &quot;Prove&quot;">​</a></h3><ul><li>Integrazione cloud (testcontainers): registrare, revocare e registrare di nuovo con lo stesso hostname restituisce lo stesso <code>id</code> e non duplica; lo stesso hostname su piattaforme diverse dà due righe; la migrazione su dati con duplicati lascia un solo dispositivo attivo per gruppo e conserva le righe; il replay dell&#39;<code>Idempotency-Key</code> continua a funzionare.</li><li>Unit desktop: <code>Logout</code> ferma la sync, chiama la revoca prima di cancellare la sessione e prosegue se la rete fallisce o l&#39;identity provider rifiuta (<code>logout_test.go</code>); <code>CLARAE_DEVICE_NAME</code> prevale sul nome del computer.</li><li><code>task test-desktop-e2e</code>: i dispositivi dei test portano nomi diversi (<code>uniqueDeviceName</code>), quindi restano due. <strong>Non provato in automatico:</strong> logout e login contro il cloud vero senza dispositivi doppi, e due istanze con <code>CLARAE_DEVICE_NAME</code> diversi: sono casi manuali del runbook <a href="./../qa/m21-correttivi.html"><code>m21-correttivi.md</code></a>.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Conservare il <code>device_id</code> nel logout</strong> (non cancellare quella parte di <code>auth.json</code>) — scartata: un logout deve poter lasciare il computer pulito, e il file resterebbe sul disco con un identificativo legato a un account che potrebbe non essere più quello che entra. Non risolve inoltre i duplicati già presenti.</li><li><strong>Un identificativo di installazione generato dal client</strong> (un UUID per installazione, inviato al cloud) — scartata: richiede un campo nuovo nel contratto, non ripulisce i duplicati esistenti e due installazioni dello stesso computer restano due dispositivi. L&#39;hostname è già il nome che l&#39;utente vede nell&#39;elenco.</li><li><strong>Solo revocare al logout, senza identità per hostname</strong> — scartata: non copre un logout senza rete, un crash, la rimozione dell&#39;app né i duplicati già presenti.</li><li><strong>Ripetere la registrazione da soli quando un <code>commit</code> è rifiutato come <code>device_id</code> sconosciuto o revocato</strong> (previsto dal piano di M21) — scartata: una revoca dalla console diventerebbe annullabile dal computer stesso al primo <code>commit</code> rifiutato, contro §1.7 («Dispositivo revocato»: il client si ferma e offre il pulsante). Il costo è che un <code>device_id</code> sconosciuto richiede un clic; il pulsante c&#39;è già e riattiva la stessa riga.</li><li><strong>Riattivare con un endpoint dedicato</strong> (per esempio <code>PUT /me/devices/{id}</code>) — scartata: serve comunque l&#39;<code>id</code>, che il client ha appena perso.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>L&#39;elenco dei dispositivi smette di crescere</strong> a ogni logout e login, e la migrazione ripulisce i duplicati esistenti senza perdere le righe a cui puntano le revisioni.</li><li><strong>Rischio accettato: due macchine dello stesso utente con lo stesso hostname e la stessa piattaforma si fondono in un solo dispositivo.</strong> Condividono <code>id</code> e <code>last_seen_at</code>; una revoca vale per entrambe. L&#39;utente le distingue rinominando una delle due; con <code>CLARAE_DEVICE_NAME</code> si può forzare un nome diverso nelle prove. Il nome host può inoltre cambiare (computer rinominato, su alcune configurazioni di macOS anche con la rete): in quel caso il computer compare come un dispositivo nuovo e il vecchio resta attivo finché non lo si revoca.</li><li><strong>Una revoca dalla console si annulla al login successivo di quella macchina</strong>, perché la registrazione riattiva la riga dello stesso hostname (<code>revoked_at = NULL</code>). La revoca resta efficace per un dispositivo che non rientra con lo stesso nome (computer perso o venduto). Per escludere davvero un utente restano la sospensione dell&#39;account e la revoca delle sessioni (§2.6.5).</li><li><strong>Punto aperto, risolto: nessuna nuova registrazione automatica.</strong> Il piano di M21 prevedeva una ripetizione della registrazione al primo <code>commit</code> rifiutato per <code>device_id</code> sconosciuto o revocato; avrebbe reso una revoca dalla console annullabile dal computer stesso. Non è implementata: §1.7 resta com&#39;è e il pulsante «Registra di nuovo questo dispositivo» è l&#39;unica via, con lo stesso risultato per l&#39;upsert (stessa riga riattivata). L&#39;owner l&#39;ha confermata accettando l&#39;ADR (2026-11-16).</li><li><strong>Un client 1.7 contro un cloud precedente</strong> continua a funzionare ma non ottiene l&#39;identità stabile: <code>RegisterDevice</code> crea una riga nuova a ogni login, come prima. La revoca al logout invece vale anche lì (<code>DELETE /me/devices/{id}</code> esiste da sempre), e la riga non resta orfana. Un cloud con la migrazione <code>0016</code> e client precedenti: il client precedente non revoca al logout, ma il login successivo riattiva la riga dello stesso hostname invece di aggiungerne una.</li><li><strong>Costi:</strong> una migrazione in avanti (nessun cambio di tipo di dati esistenti); una query nuova e il suo test; il sync del cloud e le revisioni non cambiano.</li><li><strong>Da rivedere</strong> dopo un periodo d&#39;uso su E2BR: quanti hostname in collisione compaiono, e se serve un campo per distinguere due computer con lo stesso nome.</li><li><strong>Aggiornamento del cloud.</strong> La migrazione <code>0016</code> ripulisce i duplicati: per ogni <code>(utente, piattaforma, hostname)</code> resta attivo il dispositivo con l&#39;attività più recente (un attivo vale sempre più di un revocato); gli altri si <strong>revocano</strong> e perdono il nome host, ma le righe non si cancellano. Se il <code>device_id</code> che un client ricorda è uno dei duplicati revocati, al primo <code>commit</code> rifiutato il client mostra «Registra di nuovo questo dispositivo», che riattiva la riga rimasta con quel nome. Si comunica nelle note di rilascio (CHANGELOG, <em>Compatibilità</em>).</li></ul>',19)])])}const g=o(c,[["render",n]]);export{v as __pageData,g as default};
